# CSL VPN - SoftEther Provisioning Milestone (8 commits)
$ErrorActionPreference = "Stop"
Set-Location "E:\!github\CSL-VPN"
$branch = git rev-parse --abbrev-ref HEAD
if ($branch -ne "develop") { Write-Error "Not on develop branch!"; exit 1 }
Write-Host "=== CSL VPN: SoftEther Provisioning (8 commits) ===" -ForegroundColor Cyan

$b64 = ""
$bytes = [Convert]::FromBase64String($b64)
$ms = New-Object System.IO.MemoryStream(,$bytes)
$gz = New-Object System.IO.Compression.GZipStream($ms, [System.IO.Compression.CompressionMode]::Decompress)
$sr = New-Object System.IO.StreamReader($gz)
$json = $sr.ReadToEnd()
$sr.Close(); $gz.Close(); $ms.Close()
$obj = $json | ConvertFrom-Json
$manifest = @{}
foreach ($p in $obj.PSObject.Properties) { $manifest[$p.Name] = $p.Value }

function WriteFile($relPath) {
    $content = $manifest[$relPath]
    if (!$content) { Write-Error "Missing file in manifest: $relPath"; exit 1 }
    $full = Join-Path "E:\!github\CSL-VPN" $relPath.Replace("/", "\")
    $dir = Split-Path $full -Parent
    if (!(Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    [System.IO.File]::WriteAllText($full, $content, [System.Text.UTF8Encoding]::new($false))
}

Write-Host "[1/8] Migration 006..." -ForegroundColor Yellow
WriteFile "server/migrations/006_device_vpn_secrets.sql"
git add server/migrations/006_device_vpn_secrets.sql
